import { notify } from '@/integrations';

export async function leadNotify(lead) {
  try {
    await Promise.all([
      notify.mail({ to: '$owner', subject: 'Новая заявка', body: JSON.stringify(lead) }),
      notify.tg({ chatId: '$owner', text: 'Новая заявка: ' + lead.name })
    ]);
  } catch (e) {
    // простая стратегия повторной попытки с ограничением в 3 попытки
    for (let i = 0; i < 3; i++) {
      try {
        await Promise.all([
          notify.mail({ to: '$owner', subject: 'Новая заявка', body: JSON.stringify(lead) }),
          notify.tg({ chatId: '$owner', text: 'Новая заявка: ' + lead.name })
        ]);
        break; // успех
      } catch (_) {
        if (i === 2) {
          // логируем окончательную ошибку
          console.error('Не удалось отправить уведомление о заявке', e);
        }
      }
    }
  }
}
